$taskTexture=[ordered]@{id='arch-mid-v2';family='arch';file=$taskFile.Replace('\','/');sha256=$taskMeasure.sha256;bytes=$taskMeasure.bytes;sizePx=@($taskMeasure.image.width,$taskMeasure.image.height);alpha=@{policy='straight-rgba';bounds=$taskMeasure.image.bounds;visibleBounds=$taskMeasure.image.visibleBounds;note='Native alpha retained, including genuinely transparent opening; no trim/matte'};groundAnchorPx=$taskProxy.provisionalGroundAnchorPx;footprintPx=@{center=$taskProxy.provisionalGroundAnchorPx;width=$taskProxy.provisionalFootprintWidthPx;depth=$taskProxy.provisionalFootprintDepthPx;measurement='Visible outer foot span/front contact measured; rear ground edge hidden. Anchor/depth are provisional cap-plane compression inference, uncertainty about30texturepx. Not recovered3D geometry.'};provenance=@{method='generated';promptPath=$taskRecord.prompt;promptSha256=$taskRecord.promptSha256;toolOutputId=$taskRecord.toolOutputId;rawSha256=$taskMeasure.sha256;rawFile=$taskRaw.Replace('\','/');nativeOutputPath=$taskRecord.source;references=$taskRecord.references;corrections=@('New proportion-corrected generation; full whole-sprite baseline preserved before improved part integration');selection='Limited arch07 baseline for requested actual-case review, not confirmed contact/occlusion PASS'}}
